using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

/// <summary>
/// Which part of the file name the steps operate on.
/// </summary>
public static class ApplyToValues
{
    public const string Name = "name";
    public const string NameAndExtension = "nameAndExtension";
}

/// <summary>
/// Processing order of the files.
/// </summary>
public static class SortValues
{
    public const string Name = "name";
    public const string Created = "created";
    public const string Modified = "modified";
}

/// <summary>
/// The operation identifiers understood by <see cref="RenameEngine"/>.
/// </summary>
public static class OpNames
{
    public const string Replace = "replace";
    public const string Insert = "insert";
    public const string Remove = "remove";
    public const string Sequence = "sequence";
    public const string Case = "case";
    public const string Extension = "extension";

    public static readonly string[] All =
    [
        Replace, Insert, Remove, Sequence, Case, Extension
    ];
}

/// <summary>
/// A single rule step. Deliberately modelled as one flat, permissive record rather than a
/// polymorphic hierarchy: the on-disk contract is a flat object discriminated by "op", and a flat
/// shape round-trips unknown/absent members without surprises. Members not relevant to an op are
/// simply ignored by the engine.
/// </summary>
public sealed class RuleStep
{
    [JsonPropertyName("op")]
    public string Op { get; set; } = OpNames.Replace;

    // --- replace ---------------------------------------------------------
    [JsonPropertyName("find")]
    public string? Find { get; set; }

    [JsonPropertyName("replaceWith")]
    public string? ReplaceWith { get; set; }

    [JsonPropertyName("regex")]
    public bool Regex { get; set; }

    [JsonPropertyName("ignoreCase")]
    public bool IgnoreCase { get; set; }

    // --- insert ----------------------------------------------------------
    [JsonPropertyName("text")]
    public string? Text { get; set; }

    [JsonPropertyName("position")]
    public string? Position { get; set; }

    [JsonPropertyName("index")]
    public int Index { get; set; }

    // --- remove ----------------------------------------------------------
    [JsonPropertyName("from")]
    public int From { get; set; }

    [JsonPropertyName("count")]
    public int Count { get; set; }

    // --- sequence --------------------------------------------------------
    [JsonPropertyName("pattern")]
    public string? Pattern { get; set; }

    [JsonPropertyName("start")]
    public int Start { get; set; } = 1;

    [JsonPropertyName("step")]
    public int Step { get; set; } = 1;

    // --- case / extension ------------------------------------------------
    [JsonPropertyName("mode")]
    public string? Mode { get; set; }

    [JsonPropertyName("value")]
    public string? Value { get; set; }

    /// <summary>
    /// Editor-only flag. Never serialised: a saved rules file contains exactly the steps that were
    /// enabled, so the file always reproduces what the preview showed.
    /// </summary>
    [JsonIgnore]
    public bool Enabled { get; set; } = true;

    public RuleStep Clone() => (RuleStep)MemberwiseClone();
}

/// <summary>
/// A complete rule set: the contract's rules.json document.
/// </summary>
public sealed class RuleSet
{
    [JsonPropertyName("applyTo")]
    public string ApplyTo { get; set; } = ApplyToValues.Name;

    [JsonPropertyName("sort")]
    public string Sort { get; set; } = SortValues.Name;

    [JsonPropertyName("steps")]
    public List<RuleStep> Steps { get; set; } = [];

    public bool AppliesToWholeName =>
        string.Equals(ApplyTo, ApplyToValues.NameAndExtension, StringComparison.OrdinalIgnoreCase);

    private static readonly JsonSerializerOptions ReadOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        AllowTrailingCommas = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        NumberHandling = JsonNumberHandling.AllowReadingFromString,
    };

    private static readonly JsonSerializerOptions WriteOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.Never,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public static RuleSet Parse(string json)
    {
        var parsed = JsonSerializer.Deserialize<RuleSet>(json, ReadOptions)
                     ?? throw new JsonException("rules document is null");
        parsed.ApplyTo ??= ApplyToValues.Name;
        parsed.Sort ??= SortValues.Name;
        parsed.Steps ??= [];
        foreach (var step in parsed.Steps)
        {
            step.Op ??= string.Empty;
            step.Enabled = true;
        }
        return parsed;
    }

    public static RuleSet Load(string path) => Parse(File.ReadAllText(path));

    /// <summary>
    /// Serialises only the enabled steps, so the written document is exactly contract-shaped.
    /// </summary>
    public string ToJson()
    {
        var snapshot = new RuleSet
        {
            ApplyTo = ApplyTo,
            Sort = Sort,
            Steps = Steps.Where(s => s.Enabled).Select(s => s.Clone()).ToList(),
        };
        return JsonSerializer.Serialize(snapshot, WriteOptions);
    }

    public RuleSet WithEnabledStepsOnly() => new()
    {
        ApplyTo = ApplyTo,
        Sort = Sort,
        Steps = Steps.Where(s => s.Enabled).ToList(),
    };

    public RuleSet Clone() => new()
    {
        ApplyTo = ApplyTo,
        Sort = Sort,
        Steps = Steps.Select(s => s.Clone()).ToList(),
    };
}

