namespace BatchRenameStudio.Core;

/// <summary>
/// One candidate file. Only the fields the engine needs, so the engine stays testable without a
/// real directory behind it.
/// </summary>
public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc)
{
    public static FileEntry From(FileInfo info) =>
        new(info.Name, info.CreationTimeUtc, info.LastWriteTimeUtc);
}

public static class FileScanner
{
    /// <summary>
    /// Contract rule 1: regular files directly inside <paramref name="directory"/>, non-recursive,
    /// directories excluded entirely. <see cref="DirectoryInfo.EnumerateFiles()"/> already yields
    /// only non-directory entries at the top level, which is exactly that set.
    /// </summary>
    public static List<FileEntry> Scan(string directory)
    {
        var info = new DirectoryInfo(directory);
        var entries = new List<FileEntry>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            entries.Add(FileEntry.From(file));
        }
        return entries;
    }
}

