using System.Globalization;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// The pure, deterministic core: given a file list and a rule set, produce a rename plan.
/// Every numbered comment below refers to the numbered rule in the tool's fixed contract.
///
/// Determinism notes: all casing uses the invariant culture, all comparisons are ordinal or
/// ordinal-ignore-case, and every tie-break is explicit. No ambient culture, clock or locale can
/// influence the output.
/// </summary>
public static class RenameEngine
{
    private const int MaxNameLength = 255;

    /// <summary>Rule 13: characters that make a proposed name invalid.</summary>
    private static readonly char[] InvalidNameChars = ['<', '>', ':', '"', '/', '\\', '|', '?', '*'];

    /// <summary>Rule 13: Windows reserved device names, compared case-insensitively.</summary>
    private static readonly HashSet<string> ReservedNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    };

    /// <summary>Rule 9: the single "{n:PAD}" token inside a sequence pattern.</summary>
    private static readonly Regex SequenceToken =
        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    // ------------------------------------------------------------------ public API

    /// <summary>Scans <paramref name="directory"/> and builds the plan for it.</summary>
    public static RenamePlan BuildPlan(string directory, RuleSet rules) =>
        BuildPlan(FileScanner.Scan(directory), rules);

    public static RenamePlan BuildPlan(IReadOnlyList<FileEntry> files, RuleSet rules)
    {
        var plan = new RenamePlan();
        var ordered = SortFiles(files, rules.Sort);
        var steps = Compile(rules.Steps, plan.Warnings);
        var wholeName = rules.AppliesToWholeName;

        // Rule 4/5: steps run in array order, files in processing order; the sequence counter
        // advances once per file regardless of the status that file ends up with.
        var proposed = new string[ordered.Count];
        for (var i = 0; i < ordered.Count; i++)
        {
            proposed[i] = Transform(ordered[i].Name, steps, wholeName, i);
        }

        var existing = new HashSet<string>(ordered.Select(f => f.Name), StringComparer.OrdinalIgnoreCase);
        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in proposed)
        {
            proposedCounts.TryGetValue(name, out var count);
            proposedCounts[name] = count + 1;
        }

        for (var i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var candidate = proposed[i];
            var (status, reason) = Classify(original, candidate, existing, proposedCounts);
            plan.Items.Add(new PlanItem
            {
                Original = original,
                Proposed = candidate,
                Status = status,
                Reason = reason,
            });
        }

        plan.Summary = Summarise(plan.Items);
        return plan;
    }

    /// <summary>
    /// Rule 2: split on the LAST '.'; a leading dot does not start an extension, and the returned
    /// extension never contains the dot.
    /// </summary>
    public static void SplitName(string name, out string baseName, out string extension)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            baseName = name[..dot];
            extension = name[(dot + 1)..];
        }
        else
        {
            baseName = name;
            extension = string.Empty;
        }
    }

    /// <summary>Rule 12: base + "." + ext, or just base when the extension is empty.</summary>
    public static string JoinName(string baseName, string extension) =>
        extension.Length > 0 ? baseName + "." + extension : baseName;

    // ------------------------------------------------------------------ ordering

    /// <summary>
    /// Rule 5. "name" is ordinal (codepoint) ascending and case-sensitive. The timestamp modes sort
    /// ascending and fall back to the ordinal name so that equal timestamps still yield one fixed
    /// order (rule 15).
    /// </summary>
    public static List<FileEntry> SortFiles(IReadOnlyList<FileEntry> files, string? sort)
    {
        var copy = files.ToList();
        if (string.Equals(sort, SortValues.Created, StringComparison.OrdinalIgnoreCase))
        {
            copy.Sort((a, b) =>
            {
                var byTime = a.CreatedUtc.CompareTo(b.CreatedUtc);
                return byTime != 0 ? byTime : string.CompareOrdinal(a.Name, b.Name);
            });
        }
        else if (string.Equals(sort, SortValues.Modified, StringComparison.OrdinalIgnoreCase))
        {
            copy.Sort((a, b) =>
            {
                var byTime = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                return byTime != 0 ? byTime : string.CompareOrdinal(a.Name, b.Name);
            });
        }
        else
        {
            copy.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));
        }
        return copy;
    }

    // ------------------------------------------------------------------ compilation

    /// <summary>
    /// A step whose per-run work (regex construction, token lookup) has been done once instead of
    /// once per file. Steps that cannot be honoured are dropped here, with a warning.
    /// </summary>
    private sealed class CompiledStep
    {
        public required RuleStep Source { get; init; }
        public Regex? Regex { get; init; }
    }

    private static List<CompiledStep> Compile(IEnumerable<RuleStep> steps, List<string> warnings)
    {
        var compiled = new List<CompiledStep>();
        var ordinal = 0;
        foreach (var step in steps)
        {
            ordinal++;
            var op = (step.Op ?? string.Empty).Trim();
            if (!OpNames.All.Contains(op, StringComparer.OrdinalIgnoreCase))
            {
                warnings.Add($"step {ordinal}: unknown op '{op}' was ignored");
                continue;
            }

            Regex? regex = null;
            if (string.Equals(op, OpNames.Replace, StringComparison.OrdinalIgnoreCase))
            {
                if (step.Find is null)
                {
                    warnings.Add($"step {ordinal}: replace without 'find' was ignored");
                    continue;
                }
                if (step.Regex)
                {
                    var options = RegexOptions.CultureInvariant;
                    if (step.IgnoreCase)
                    {
                        options |= RegexOptions.IgnoreCase;
                    }
                    try
                    {
                        regex = new Regex(step.Find, options);
                    }
                    catch (ArgumentException ex)
                    {
                        warnings.Add($"step {ordinal}: invalid regex '{step.Find}' was ignored ({ex.Message})");
                        continue;
                    }
                }
                else if (step.Find.Length == 0)
                {
                    // A literal empty needle has no meaningful replacement semantics.
                    warnings.Add($"step {ordinal}: replace with an empty literal 'find' was ignored");
                    continue;
                }
            }

            compiled.Add(new CompiledStep { Source = step, Regex = regex });
        }
        return compiled;
    }

    // ------------------------------------------------------------------ transformation

    /// <summary>
    /// Rules 3, 4, 11 and 12. Under "name" the steps see the base and an <c>extension</c> step sees
    /// the separate extension; under "nameAndExtension" the steps see the whole file name and an
    /// <c>extension</c> step re-splits the current string and rewrites its trailing extension.
    /// </summary>
    private static string Transform(string originalName, List<CompiledStep> steps, bool wholeName, int index)
    {
        if (wholeName)
        {
            // Rule 3/12: the target string IS the whole file name, and the result of the last step
            // IS the proposed name.
            var target = originalName;
            foreach (var step in steps)
            {
                if (IsExtensionOp(step))
                {
                    SplitName(target, out var b, out var e);
                    target = JoinName(b, ApplyExtension(e, step.Source));
                }
                else
                {
                    target = ApplyToTarget(target, step, index);
                }
            }
            return target;
        }

        SplitName(originalName, out var baseName, out var extension);
        foreach (var step in steps)
        {
            if (IsExtensionOp(step))
            {
                extension = ApplyExtension(extension, step.Source);
            }
            else
            {
                baseName = ApplyToTarget(baseName, step, index);
            }
        }
        return JoinName(baseName, extension);
    }

    private static bool IsExtensionOp(CompiledStep step) =>
        string.Equals(step.Source.Op, OpNames.Extension, StringComparison.OrdinalIgnoreCase);

    private static string ApplyToTarget(string target, CompiledStep step, int index)
    {
        var rule = step.Source;
        return (rule.Op ?? string.Empty).ToLowerInvariant() switch
        {
            OpNames.Replace => ApplyReplace(target, step),
            OpNames.Insert => ApplyInsert(target, rule),
            OpNames.Remove => ApplyRemove(target, rule),
            OpNames.Sequence => ApplySequence(target, rule, index),
            OpNames.Case => ApplyCase(target, rule),
            _ => target,
        };
    }

    /// <summary>Rule 6: replace ALL occurrences; regex mode supports $1 group references.</summary>
    private static string ApplyReplace(string target, CompiledStep step)
    {
        var rule = step.Source;
        var with = rule.ReplaceWith ?? string.Empty;
        if (step.Regex is not null)
        {
            return step.Regex.Replace(target, with);
        }

        var comparison = rule.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        return target.Replace(rule.Find!, with, comparison);
    }

    /// <summary>Rule 7: prefix / suffix / index, with index clamped to [0, length].</summary>
    private static string ApplyInsert(string target, RuleStep rule)
    {
        var text = rule.Text ?? string.Empty;
        if (string.Equals(rule.Position, "suffix", StringComparison.OrdinalIgnoreCase))
        {
            return target + text;
        }
        if (string.Equals(rule.Position, "index", StringComparison.OrdinalIgnoreCase))
        {
            var at = Math.Clamp(rule.Index, 0, target.Length);
            return target.Insert(at, text);
        }
        // "prefix" and anything unrecognised.
        return text + target;
    }

    /// <summary>Rule 8: from clamped to [0, length], count clamped to what remains.</summary>
    private static string ApplyRemove(string target, RuleStep rule)
    {
        var from = Math.Clamp(rule.From, 0, target.Length);
        var count = Math.Clamp(rule.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    /// <summary>Rule 9: render "{n:PAD}" with the counter for this file's processing position.</summary>
    private static string ApplySequence(string target, RuleStep rule, int index)
    {
        var counter = (long)rule.Start + (long)rule.Step * index;
        var rendered = RenderSequence(rule.Pattern ?? string.Empty, counter);
        return string.Equals(rule.Position, "suffix", StringComparison.OrdinalIgnoreCase)
            ? target + rendered
            : rendered + target;
    }

    public static string RenderSequence(string pattern, long counter)
    {
        var match = SequenceToken.Match(pattern);
        if (!match.Success)
        {
            // No token: the pattern is pure literal text.
            return pattern;
        }
        var width = match.Groups[1].Value.Length;
        var number = counter.ToString(new string('0', width), CultureInfo.InvariantCulture);
        return string.Concat(pattern.AsSpan(0, match.Index), number, pattern.AsSpan(match.Index + match.Length));
    }

    /// <summary>Rule 10.</summary>
    private static string ApplyCase(string target, RuleStep rule) =>
        (rule.Mode ?? string.Empty).ToLowerInvariant() switch
        {
            "upper" => target.ToUpperInvariant(),
            "lower" => target.ToLowerInvariant(),
            "title" => ToTitleCase(target),
            _ => target,
        };

    /// <summary>
    /// Rule 10: within each maximal run of Unicode letters the first character is uppercased and
    /// the rest lowercased; every non-letter is left exactly as it was and ends the run.
    /// </summary>
    public static string ToTitleCase(string value)
    {
        var chars = value.ToCharArray();
        var atRunStart = true;
        for (var i = 0; i < chars.Length; i++)
        {
            if (char.IsLetter(chars[i]))
            {
                chars[i] = atRunStart ? char.ToUpperInvariant(chars[i]) : char.ToLowerInvariant(chars[i]);
                atRunStart = false;
            }
            else
            {
                atRunStart = true;
            }
        }
        return new string(chars);
    }

    /// <summary>Rule 11: lower / upper / set, always against the extension (never the base).</summary>
    private static string ApplyExtension(string extension, RuleStep rule) =>
        (rule.Mode ?? string.Empty).ToLowerInvariant() switch
        {
            "lower" => extension.ToLowerInvariant(),
            "upper" => extension.ToUpperInvariant(),
            "set" => rule.Value ?? string.Empty,
            _ => extension,
        };

    // ------------------------------------------------------------------ classification

    /// <summary>Rule 13, evaluated in the contract's precedence order; first match wins.</summary>
    private static (string Status, string Reason) Classify(
        string original,
        string proposed,
        HashSet<string> existingNames,
        Dictionary<string, int> proposedCounts)
    {
        var invalidReason = DescribeInvalid(proposed);
        if (invalidReason is not null)
        {
            return (PlanStatus.Invalid, invalidReason);
        }

        // "an existing file other than this item": an existing name matching case-insensitively is
        // this item's own file exactly when the proposal also matches the original that way.
        var hitsAnotherFile = existingNames.Contains(proposed)
                              && !string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase);
        if (hitsAnotherFile)
        {
            return (PlanStatus.Collision, "target name already exists in the folder");
        }

        if (proposedCounts.TryGetValue(proposed, out var count) && count > 1)
        {
            return (PlanStatus.Collision, "another file is proposed to take the same name");
        }

        if (string.Equals(proposed, original, StringComparison.Ordinal))
        {
            return (PlanStatus.Unchanged, "the rules leave this name as it is");
        }

        return (PlanStatus.Ok, string.Empty);
    }

    /// <summary>Returns a reason when the proposed name is invalid, or null when it is usable.</summary>
    public static string? DescribeInvalid(string proposed)
    {
        if (proposed.Length == 0)
        {
            return "the proposed name is empty";
        }
        if (proposed.Length > MaxNameLength)
        {
            return $"the proposed name is longer than {MaxNameLength} characters";
        }
        foreach (var c in proposed)
        {
            if (c < ' ')
            {
                return "the proposed name contains a control character";
            }
            if (Array.IndexOf(InvalidNameChars, c) >= 0)
            {
                return $"the proposed name contains the illegal character '{c}'";
            }
        }
        SplitName(proposed, out var baseName, out _);
        if (ReservedNames.Contains(baseName))
        {
            return $"'{baseName}' is a reserved Windows device name";
        }
        return null;
    }

    private static PlanSummary Summarise(IEnumerable<PlanItem> items)
    {
        var summary = new PlanSummary();
        foreach (var item in items)
        {
            summary.Total++;
            switch (item.Status)
            {
                case PlanStatus.Ok: summary.Ok++; break;
                case PlanStatus.Collision: summary.Collision++; break;
                case PlanStatus.Unchanged: summary.Unchanged++; break;
                case PlanStatus.Invalid: summary.Invalid++; break;
            }
        }
        return summary;
    }
}

