using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

/// <summary>One rename that actually happened on disk.</summary>
public sealed class RenameRecord
{
    [JsonPropertyName("from")]
    public string From { get; set; } = string.Empty;

    [JsonPropertyName("to")]
    public string To { get; set; } = string.Empty;
}

/// <summary>
/// A completed batch. This is the undo unit: undo replays the batch backwards, which is safe even
/// when the batch shuffled names among each other.
/// </summary>
public sealed class RenameBatch
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = string.Empty;

    [JsonPropertyName("directory")]
    public string Directory { get; set; } = string.Empty;

    [JsonPropertyName("timestampUtc")]
    public DateTime TimestampUtc { get; set; }

    [JsonPropertyName("records")]
    public List<RenameRecord> Records { get; set; } = [];

    [JsonIgnore]
    public string Label =>
        $"{TimestampUtc.ToLocalTime():yyyy-MM-dd HH:mm:ss}  ·  {Records.Count} file(s)  ·  {Directory}";
}

public sealed class ApplyOutcome
{
    public int Renamed { get; set; }
    public int Skipped { get; set; }
    public List<string> Failures { get; } = [];
    public RenameBatch? Batch { get; set; }
}

/// <summary>
/// Performs the renames a plan proposes, and reverses them.
///
/// Only <c>ok</c> items are executed. The plan already guarantees that no <c>ok</c> target collides
/// with an existing file or with another proposal, so a single forward pass is enough; the one case
/// needing care is a rename that only changes letter case, which goes through a temporary name
/// because the file system treats source and target as the same entry.
/// </summary>
public static class RenameApplier
{
    public static ApplyOutcome Apply(string directory, RenamePlan plan)
    {
        var outcome = new ApplyOutcome();
        var batch = new RenameBatch
        {
            Id = Guid.NewGuid().ToString("N"),
            Directory = directory,
            TimestampUtc = DateTime.UtcNow,
        };

        foreach (var item in plan.Items)
        {
            if (item.Status != PlanStatus.Ok)
            {
                outcome.Skipped++;
                continue;
            }

            var source = Path.Combine(directory, item.Original);
            var target = Path.Combine(directory, item.Proposed);
            try
            {
                MoveFile(source, target);
                batch.Records.Add(new RenameRecord { From = item.Original, To = item.Proposed });
                outcome.Renamed++;
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                outcome.Failures.Add($"{item.Original} -> {item.Proposed}: {ex.Message}");
            }
        }

        if (batch.Records.Count > 0)
        {
            outcome.Batch = batch;
        }
        return outcome;
    }

    /// <summary>Replays a batch backwards. Returns the list of entries that could not be reverted.</summary>
    public static List<string> Undo(RenameBatch batch)
    {
        var failures = new List<string>();
        for (var i = batch.Records.Count - 1; i >= 0; i--)
        {
            var record = batch.Records[i];
            var current = Path.Combine(batch.Directory, record.To);
            var restored = Path.Combine(batch.Directory, record.From);
            try
            {
                if (!File.Exists(current))
                {
                    failures.Add($"{record.To}: the file is no longer there");
                    continue;
                }
                MoveFile(current, restored);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                failures.Add($"{record.To} -> {record.From}: {ex.Message}");
            }
        }
        return failures;
    }

    private static void MoveFile(string source, string target)
    {
        if (string.Equals(source, target, StringComparison.Ordinal))
        {
            return;
        }

        var caseOnly = string.Equals(source, target, StringComparison.OrdinalIgnoreCase);
        if (!caseOnly)
        {
            if (File.Exists(target) || Directory.Exists(target))
            {
                throw new IOException("the target name is already taken");
            }
            File.Move(source, target);
            return;
        }

        // Case-only rename: hop through a name that certainly does not exist so the file system
        // cannot mistake the target for the source.
        var directory = Path.GetDirectoryName(target) ?? string.Empty;
        var temporary = Path.Combine(directory, $".brs-tmp-{Guid.NewGuid():N}");
        File.Move(source, temporary);
        try
        {
            File.Move(temporary, target);
        }
        catch
        {
            File.Move(temporary, source);
            throw;
        }
    }
}

