using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Batch Rename Studio ships as a single Windows-subsystem executable so that double-clicking it
/// never flashes a console window. A Windows-subsystem process, however, starts with no standard
/// output at all when it is launched from a shell without redirection, so headless mode borrows the
/// parent process's console before anything is written.
///
/// Three situations, all handled:
///   * stdout is redirected (a pipe or a file) - the handle is already valid, nothing to attach.
///   * launched from a console with no redirection - attach to the parent console.
///   * launched with no console at all (Explorer, a service) - writes are silently discarded.
/// </summary>
internal static class ConsoleBridge
{
    private const int AttachParentProcess = -1;
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;

    private static bool _attached;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    public static void Attach()
    {
        if (_attached)
        {
            return;
        }
        _attached = true;

        if (!HasHandle(StdOutputHandle) || !HasHandle(StdErrorHandle))
        {
            AttachConsole(AttachParentProcess);
        }

        Rebind(Console.SetOut, Console.OpenStandardOutput);
        Rebind(Console.SetError, Console.OpenStandardError);
    }

    private static bool HasHandle(int which)
    {
        var handle = GetStdHandle(which);
        return handle != IntPtr.Zero && handle != new IntPtr(-1);
    }

    private static void Rebind(Action<TextWriter> setter, Func<Stream> opener)
    {
        Stream stream;
        try
        {
            stream = opener();
        }
        catch (IOException)
        {
            return;
        }

        if (ReferenceEquals(stream, Stream.Null))
        {
            return;
        }

        // UTF-8 without a BOM: the summary line must not be prefixed with stray bytes.
        setter(new StreamWriter(stream, new UTF8Encoding(false)) { AutoFlush = true });
    }
}

