namespace BatchRenameStudio.Cli;

internal enum CliMode
{
    Gui,
    Plan,
    Apply,
    SelfTest,
    Help,
    Version,
    Error,
}

internal sealed class CliOptions
{
    public CliMode Mode { get; set; } = CliMode.Gui;
    public string? Directory { get; set; }
    public string? RulesPath { get; set; }
    public string? OutPath { get; set; }
    public bool Yes { get; set; }
    public string? Error { get; set; }
}

/// <summary>
/// Minimal, dependency-free argument parsing. Accepts "--flag value" and "--flag=value".
/// With no recognised mode flag the tool starts its window; a bare path argument preselects the
/// folder the window opens on.
/// </summary>
internal static class CommandLine
{
    public static CliOptions Parse(string[] args)
    {
        var options = new CliOptions();
        if (args.Length == 0)
        {
            return options;
        }

        for (var i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            var (flag, inlineValue) = SplitInline(arg);

            switch (flag.ToLowerInvariant())
            {
                case "--plan":
                    options.Mode = CliMode.Plan;
                    break;
                case "--apply":
                    options.Mode = CliMode.Apply;
                    break;
                case "--selftest":
                case "--self-test":
                    options.Mode = CliMode.SelfTest;
                    break;
                case "--help":
                case "-h":
                case "-?":
                case "/?":
                    options.Mode = CliMode.Help;
                    return options;
                case "--version":
                    options.Mode = CliMode.Version;
                    return options;
                case "--yes":
                case "-y":
                    options.Yes = true;
                    break;
                case "--dir":
                    if (!TryTakeValue(args, ref i, inlineValue, flag, options, out var dir))
                    {
                        return options;
                    }
                    options.Directory = dir;
                    break;
                case "--rules":
                    if (!TryTakeValue(args, ref i, inlineValue, flag, options, out var rules))
                    {
                        return options;
                    }
                    options.RulesPath = rules;
                    break;
                case "--out":
                    if (!TryTakeValue(args, ref i, inlineValue, flag, options, out var outPath))
                    {
                        return options;
                    }
                    options.OutPath = outPath;
                    break;
                default:
                    if (flag.StartsWith('-'))
                    {
                        return Fail(options, $"unknown option '{flag}'");
                    }
                    // A bare argument is a folder for the window to open on.
                    options.Directory ??= arg;
                    break;
            }
        }

        return options;
    }

    private static (string Flag, string? Value) SplitInline(string arg)
    {
        var equals = arg.IndexOf('=');
        if (arg.StartsWith('-') && equals > 0)
        {
            return (arg[..equals], arg[(equals + 1)..]);
        }
        return (arg, null);
    }

    private static bool TryTakeValue(
        string[] args, ref int i, string? inlineValue, string flag, CliOptions options, out string value)
    {
        if (inlineValue is not null)
        {
            value = inlineValue;
            return true;
        }
        if (i + 1 >= args.Length)
        {
            value = string.Empty;
            Fail(options, $"option '{flag}' needs a value");
            return false;
        }
        value = args[++i];
        return true;
    }

    private static CliOptions Fail(CliOptions options, string message)
    {
        options.Mode = CliMode.Error;
        options.Error = message;
        return options;
    }

    public const string HelpText = """
        Batch Rename Studio 1.0

        GUI:
          BatchRenameStudio.exe [folder]

        Headless planning (never touches a file):
          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>

        Headless apply (renames the files a plan marks "ok"):
          BatchRenameStudio.exe --apply --dir <folder> --rules <rules.json> [--out <plan.json>] --yes

        Built-in contract self-test:
          BatchRenameStudio.exe --selftest

        Options:
          --dir <folder>       folder to scan; only the files directly inside it are considered
          --rules <file>       rule set document (see README.md for the schema)
          --out <file>         where to write plan.json (UTF-8, no BOM)
          --yes, -y            required by --apply; confirms the renames non-interactively
          --help, -h           show this text
          --version            print the version

        Exit codes:
          0  success
          1  the operation ran but something failed (e.g. a rename could not be performed)
          2  bad usage, missing input, or unreadable rules
        """;
}

