using System.Text.Json;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

internal static class ExitCodes
{
    public const int Success = 0;
    public const int OperationFailed = 1;
    public const int UsageError = 2;
}

/// <summary>
/// The headless entry points. Contract obligations for <c>--plan</c>:
/// exit 0 on success, exactly one line on stdout, plan.json written as UTF-8 without a BOM, and
/// not a single file touched.
/// </summary>
internal static class HeadlessCommands
{
    public static int Plan(CliOptions options)
    {
