        TargetSelection();
        StepSemantics();
        SequenceSemantics();
        ExtensionSemantics();
        StatusPrecedence();
        Ordering();
        Determinism();

        Console.Out.WriteLine($"selftest: {_passed} passed, {Failures.Count} failed");
        foreach (var failure in Failures)
        {
            Console.Out.WriteLine("  FAIL " + failure);
        }
        return Failures.Count == 0 ? ExitCodes.Success : ExitCodes.OperationFailed;
    }

    // ------------------------------------------------------------------ cases

    private static void NameSplitting()
    {
        // Rule 2: a leading dot does not begin an extension.
        Check("rule 2 / dotfile keeps its whole name as the base",
            ["﻿placeholder"], "", []);   // placeholder replaced below

        Expect("rule 2 / dotfile base",
            Files(".gitignore"),
            Rules("name", "name", """{"op":"insert","text":"_x","position":"suffix"}"""),
            (".gitignore", ".gitignore_x", PlanStatus.Ok));

        Expect("rule 2 / last dot wins",
            Files("a.b.txt"),
            Rules("name", "name", """{"op":"insert","text":"-","position":"suffix"}"""),
            ("a.b.txt", "a.b-.txt", PlanStatus.Ok));

        // Rule 2 + 12: "a." splits to base "a" with an empty extension, and an empty extension is
        // reassembled without the dot.
        Expect("rule 12 / trailing dot is dropped by reassembly",
            Files("a."),
            Rules("name", "name"),
            ("a.", "a", PlanStatus.Ok));

        Expect("rule 2 / no extension at all",
            Files("README"),
            Rules("name", "name", """{"op":"insert","text":"1","position":"suffix"}"""),
            ("README", "README1", PlanStatus.Ok));
    }

    private static void TargetSelection()
    {
        // Rule 3: "name" leaves the extension out of reach of ordinary steps.
        Expect("rule 3 / applyTo name spares the extension",
            Files("a.TxT"),
            Rules("name", "name", """{"op":"case","mode":"upper"}"""),
            ("a.TxT", "A.TxT", PlanStatus.Ok));

        Expect("rule 3 / applyTo nameAndExtension covers everything",
            Files("a.TxT"),
            Rules("nameAndExtension", "name", """{"op":"case","mode":"upper"}"""),
            ("a.TxT", "A.TXT", PlanStatus.Ok));

        // Rule 4: steps chain in array order.
        Expect("rule 4 / steps chain in order",
            Files("abc.txt"),
            Rules("name", "name",
                """{"op":"insert","text":"z","position":"prefix"}""",
                """{"op":"case","mode":"upper"}"""),
            ("abc.txt", "ZABC.txt", PlanStatus.Ok));
    }

    private static void StepSemantics()
    {
        // Rule 6.
        Expect("rule 6 / replace hits every occurrence",
            Files("aaa.txt"),
            Rules("name", "name", """{"op":"replace","find":"a","replaceWith":"b"}"""),
            ("aaa.txt", "bbb.txt", PlanStatus.Ok));

        Expect("rule 6 / literal replace honours ignoreCase",
            Files("Hello.txt"),
            Rules("name", "name", """{"op":"replace","find":"hello","replaceWith":"hi","ignoreCase":true}"""),
            ("Hello.txt", "hi.txt", PlanStatus.Ok));

        Expect("rule 6 / regex replace supports $1",
            Files("img_01.jpg"),
            Rules("name", "name", """{"op":"replace","find":"img_(\\d+)","replaceWith":"$1_img","regex":true}"""),
            ("img_01.jpg", "01_img.jpg", PlanStatus.Ok));

        Expect("rule 6 / regex replace honours ignoreCase",
            Files("IMG_7.jpg"),
            Rules("name", "name", """{"op":"replace","find":"img_","replaceWith":"p","regex":true,"ignoreCase":true}"""),
            ("IMG_7.jpg", "p7.jpg", PlanStatus.Ok));

        // Rule 7.
        Expect("rule 7 / insert at prefix and suffix",
            Files("m.txt"),
            Rules("name", "name",
                """{"op":"insert","text":"<","position":"prefix"}""".Replace("<", "L"),
                """{"op":"insert","text":"R","position":"suffix"}"""),
            ("m.txt", "LmR.txt", PlanStatus.Ok));

        Expect("rule 7 / insert index is clamped upwards",
            Files("ab.txt"),
            Rules("name", "name", """{"op":"insert","text":"-","position":"index","index":99}"""),
            ("ab.txt", "ab-.txt", PlanStatus.Ok));

        Expect("rule 7 / insert index is clamped downwards",
            Files("ab.txt"),
            Rules("name", "name", """{"op":"insert","text":"-","position":"index","index":-4}"""),
            ("ab.txt", "-ab.txt", PlanStatus.Ok));

        // Rule 8.
        Expect("rule 8 / remove count is clamped to what remains",
            Files("abc.txt"),
            Rules("name", "name", """{"op":"remove","from":1,"count":100}"""),
            ("abc.txt", "a.txt", PlanStatus.Ok));

        Expect("rule 8 / remove from is clamped to zero",
            Files("abc.txt"),
            Rules("name", "name", """{"op":"remove","from":-5,"count":2}"""),
            ("abc.txt", "c.txt", PlanStatus.Ok));

        // Rule 10.
        Expect("rule 10 / title case per run of letters",
            Files("hello wOrld-foo2bar.TXT"),
            Rules("name", "name", """{"op":"case","mode":"title"}"""),
            ("hello wOrld-foo2bar.TXT", "Hello World-Foo2Bar.TXT", PlanStatus.Ok));

        Expect("rule 10 / title case leaves non-letters alone",
            Files("__a__b.txt"),
            Rules("name", "name", """{"op":"case","mode":"title"}"""),
            ("__a__b.txt", "__A__B.txt", PlanStatus.Ok));
    }

    private static void SequenceSemantics()
    {
        // Rule 9: pad width, start and step.
        Expect("rule 9 / pad, start and step",
            Files("a.txt", "b.txt", "c.txt"),
            Rules("name", "name", """{"op":"sequence","pattern":"{n:00}_","start":5,"step":2,"position":"prefix"}"""),
            ("a.txt", "05_a.txt", PlanStatus.Ok),
            ("b.txt", "07_b.txt", PlanStatus.Ok),
            ("c.txt", "09_c.txt", PlanStatus.Ok));

        Expect("rule 9 / suffix placement and literal text around the token",
            Files("a.txt", "b.txt"),
            Rules("name", "name", """{"op":"sequence","pattern":"-v{n:000}","start":1,"step":1,"position":"suffix"}"""),
            ("a.txt", "a-v001.txt", PlanStatus.Ok),
            ("b.txt", "b-v002.txt", PlanStatus.Ok));

        // Rule 9: the counter advances for every file, even one that ends up invalid.
        Expect("rule 9 / the counter ignores the resulting status",
            Files("a.txt", "b.txt", "c.txt"),
            Rules("name", "name",
                """{"op":"replace","find":"b","replaceWith":"b:"}""",
                """{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}"""),
            ("a.txt", "1_a.txt", PlanStatus.Ok),
            ("b.txt", "2_b:.txt", PlanStatus.Invalid),
            ("c.txt", "3_c.txt", PlanStatus.Ok));
    }

    private static void ExtensionSemantics()
    {
        // Rule 11.
        Expect("rule 11 / extension lower",
            Files("a.TXT"),
            Rules("name", "name", """{"op":"extension","mode":"lower"}"""),
            ("a.TXT", "a.txt", PlanStatus.Ok));

        Expect("rule 11 / extension set gives an extension to a file without one",
            Files("README"),
            Rules("name", "name", """{"op":"extension","mode":"set","value":"txt"}"""),
            ("README", "README.txt", PlanStatus.Ok));

        // Rule 11: the extension step ignores applyTo and still reaches the extension.
        Expect("rule 11 / extension step works under applyTo name",
            Files("a.TXT"),
            Rules("name", "name",
                """{"op":"case","mode":"upper"}""",
                """{"op":"extension","mode":"lower"}"""),
            ("a.TXT", "A.txt", PlanStatus.Ok));

        // Rule 12: under nameAndExtension the extension step re-splits the current string.
        Expect("rule 12 / extension step targets the trailing extension of the running string",
            Files("note.txt"),
            Rules("nameAndExtension", "name",
                """{"op":"insert","text":"_v2","position":"suffix"}""",
                """{"op":"extension","mode":"set","value":"md"}"""),
            ("note.txt", "note.md", PlanStatus.Ok));
    }

    private static void StatusPrecedence()
    {
        // Rule 13, first bullet.
        Expect("rule 13 / illegal character is invalid",
            Files("a.txt"),
            Rules("name", "name", """{"op":"insert","text":"?","position":"prefix"}"""),
            ("a.txt", "?a.txt", PlanStatus.Invalid));

        Expect("rule 13 / reserved device name is invalid",
            Files("x.txt"),
            Rules("name", "name", """{"op":"replace","find":"x","replaceWith":"con"}"""),
            ("x.txt", "con.txt", PlanStatus.Invalid));

        Expect("rule 13 / an empty proposed name is invalid",
            Files("ab"),
            Rules("name", "name", """{"op":"remove","from":0,"count":2}"""),
            ("ab", "", PlanStatus.Invalid));

        Expect("rule 13 / names longer than 255 characters are invalid",
            Files("a.txt"),
            Rules("name", "name", $$"""{"op":"insert","text":"{{new string('x', 260)}}","position":"prefix"}"""),
            ("a.txt", new string('x', 260) + "a.txt", PlanStatus.Invalid));

        // Rule 13, second bullet.
        Expect("rule 13 / colliding with an existing file",
            Files("a.txt", "b.txt"),
            Rules("name", "name", """{"op":"replace","find":"a","replaceWith":"b"}"""),
            ("a.txt", "b.txt", PlanStatus.Collision),
            ("b.txt", "b.txt", PlanStatus.Unchanged));

        Expect("rule 13 / two proposals claiming one name",
            Files("a1.txt", "a2.txt"),
            Rules("name", "name", """{"op":"remove","from":1,"count":1}"""),
            ("a1.txt", "a.txt", PlanStatus.Collision),
            ("a2.txt", "a.txt", PlanStatus.Collision));

        // Rule 13: invalid outranks collision.
        Expect("rule 13 / invalid outranks collision",
            Files("a1.txt", "a2.txt"),
            Rules("name", "name",
                """{"op":"remove","from":1,"count":1}""",
                """{"op":"insert","text":"|","position":"prefix"}"""),
            ("a1.txt", "|a.txt", PlanStatus.Invalid),
            ("a2.txt", "|a.txt", PlanStatus.Invalid));

        // Rule 13: a case-only change is neither a self-collision nor unchanged.
        Expect("rule 13 / a case-only change is ok",
            Files("a.txt"),
            Rules("name", "name", """{"op":"case","mode":"upper"}"""),
            ("a.txt", "A.txt", PlanStatus.Ok));

        // Rule 13, third bullet: "unchanged" compares exactly.
        Expect("rule 13 / no steps leaves everything unchanged",
            Files("a.txt", "b.txt"),
            Rules("name", "name"),
            ("a.txt", "a.txt", PlanStatus.Unchanged),
            ("b.txt", "b.txt", PlanStatus.Unchanged));
    }

    private static void Ordering()
    {
        // Rule 5 / 14: ordinal, case-sensitive, so uppercase sorts before lowercase.
        Expect("rule 5 / name order is ordinal and case-sensitive",
            Files("b.txt", "A.txt", "a.txt", "B.txt"),
            Rules("name", "name", """{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}"""),
            ("A.txt", "1_A.txt", PlanStatus.Ok),
            ("B.txt", "2_B.txt", PlanStatus.Ok),
            ("a.txt", "3_a.txt", PlanStatus.Ok),
            ("b.txt", "4_b.txt", PlanStatus.Ok));

        var stamped = new List<FileEntry>
        {
            new("late.txt", new DateTime(2024, 1, 3, 0, 0, 0, DateTimeKind.Utc), new DateTime(2024, 5, 1, 0, 0, 0, DateTimeKind.Utc)),
            new("early.txt", new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), new DateTime(2024, 5, 3, 0, 0, 0, DateTimeKind.Utc)),
            new("mid.txt", new DateTime(2024, 1, 2, 0, 0, 0, DateTimeKind.Utc), new DateTime(2024, 5, 2, 0, 0, 0, DateTimeKind.Utc)),
        };

        Expect("rule 5 / created ascending",
            stamped,
            Rules("name", "created", """{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}"""),
            ("early.txt", "1_early.txt", PlanStatus.Ok),
            ("mid.txt", "2_mid.txt", PlanStatus.Ok),
            ("late.txt", "3_late.txt", PlanStatus.Ok));

        Expect("rule 5 / modified ascending",
            stamped,
            Rules("name", "modified", """{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}"""),
            ("late.txt", "1_late.txt", PlanStatus.Ok),
            ("mid.txt", "2_mid.txt", PlanStatus.Ok),
            ("early.txt", "3_early.txt", PlanStatus.Ok));
    }

    private static void Determinism()
    {
        // Rule 15.
        var files = Files("b.txt", "a.TXT", "c");
        var rules = Rules("name", "name",
            """{"op":"case","mode":"title"}""",
            """{"op":"sequence","pattern":"{n:000}-","start":1,"step":1,"position":"prefix"}""",
            """{"op":"extension","mode":"lower"}""");

        var first = RenameEngine.BuildPlan(files, RuleSet.Parse(rules)).ToJson();
        var second = RenameEngine.BuildPlan(files, RuleSet.Parse(rules)).ToJson();
        if (first == second)
        {
            _passed++;
        }
        else
        {
            Failures.Add("rule 15 / repeated planning produced different documents");
        }

        // The summary must agree with the item list.
        var plan = RenameEngine.BuildPlan(
            Files("a.txt", "b.txt", "c1.txt", "c2.txt"),
            RuleSet.Parse(Rules("name", "name",
                """{"op":"replace","find":"a","replaceWith":"b"}""",
                """{"op":"replace","find":"c1","replaceWith":"c"}""",
                """{"op":"replace","find":"c2","replaceWith":"c"}""")));
        var expected = $"{plan.Items.Count}/" +
                       $"{plan.Items.Count(i => i.Status == PlanStatus.Ok)}/" +
                       $"{plan.Items.Count(i => i.Status == PlanStatus.Collision)}/" +
                       $"{plan.Items.Count(i => i.Status == PlanStatus.Unchanged)}/" +
                       $"{plan.Items.Count(i => i.Status == PlanStatus.Invalid)}";
        var actual = $"{plan.Summary.Total}/{plan.Summary.Ok}/{plan.Summary.Collision}/" +
                     $"{plan.Summary.Unchanged}/{plan.Summary.Invalid}";
        if (expected == actual)
        {
            _passed++;
        }
        else
        {
            Failures.Add($"summary counts / expected {expected} but the summary says {actual}");
        }
    }

    // ------------------------------------------------------------------ helpers

    private static List<FileEntry> Files(params string[] names)
    {
        var seed = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        return names
            .Select((n, i) => new FileEntry(n, seed.AddMinutes(i), seed.AddMinutes(i)))
            .ToList();
    }

    private static string Rules(string applyTo, string sort, params string[] steps) =>
        $$"""{"applyTo":"{{applyTo}}","sort":"{{sort}}","steps":[{{string.Join(",", steps)}}]}""";

    private static void Expect(
        string name,
        List<FileEntry> files,
        string rulesJson,
        params (string Original, string Proposed, string Status)[] expected)
    {
        if (expected.Length == 0)
        {
            return;   // reserved placeholder, nothing to assert
        }

        try
        {
            var plan = RenameEngine.BuildPlan(files, RuleSet.Parse(rulesJson));
            if (plan.Items.Count != expected.Length)
            {
                Failures.Add($"{name}: expected {expected.Length} item(s), got {plan.Items.Count}");
                return;
            }
            for (var i = 0; i < expected.Length; i++)
            {
                var actual = plan.Items[i];
                var want = expected[i];
                if (actual.Original != want.Original || actual.Proposed != want.Proposed || actual.Status != want.Status)
                {
                    Failures.Add(
                        $"{name}: item {i} expected ({want.Original} -> {want.Proposed} [{want.Status}]) " +
                        $"but got ({actual.Original} -> {actual.Proposed} [{actual.Status}])");
                    return;
                }
            }
            _passed++;
        }
        catch (Exception ex)
        {
            Failures.Add($"{name}: threw {ex.GetType().Name}: {ex.Message}");
        }
    }

    private static void Check(string name, string[] _, string __, (string, string, string)[] ___)
    {
        // Intentionally inert: keeps the placeholder call above harmless.
        _ = name;
    }
}

