using System.Reflection;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var options = CommandLine.Parse(args);

        if (options.Mode == CliMode.Gui)
        {
            RunGui(options.Directory);
            return ExitCodes.Success;
        }

        // Everything below is headless, so borrow the parent console before writing anything.
        ConsoleBridge.Attach();

        switch (options.Mode)
        {
            case CliMode.Plan:
                return HeadlessCommands.Plan(options);
            case CliMode.Apply:
                return HeadlessCommands.Apply(options);
            case CliMode.SelfTest:
                return SelfTest.Run();
            case CliMode.Help:
                Console.Out.WriteLine(CommandLine.HelpText);
                return ExitCodes.Success;
            case CliMode.Version:
                Console.Out.WriteLine(
                    Assembly.GetExecutingAssembly().GetName().Version?.ToString(3) ?? "1.0.0");
                return ExitCodes.Success;
            default:
                Console.Error.WriteLine($"error: {options.Error}");
                Console.Error.WriteLine();
                Console.Error.WriteLine(CommandLine.HelpText);
                return ExitCodes.UsageError;
        }
    }

    private static void RunGui(string? initialDirectory)
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
        Application.Run(new MainForm(initialDirectory));
    }
}

