using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Renders a one-line human description of a step for the rule list.
/// </summary>
internal static class RuleStepText
{
    public static string Describe(RuleStep step) => (step.Op ?? string.Empty).ToLowerInvariant() switch
    {
        OpNames.Replace =>
            $"Replace {(step.Regex ? "/regex/ " : "")}“{step.Find}” with “{step.ReplaceWith}”" +
            (step.IgnoreCase ? " (any case)" : ""),
        OpNames.Insert =>
            string.Equals(step.Position, "index", StringComparison.OrdinalIgnoreCase)
                ? $"Insert “{step.Text}” at position {step.Index}"
                : $"Insert “{step.Text}” as {Pos(step.Position)}",
        OpNames.Remove => $"Remove {step.Count} character(s) from position {step.From}",
        OpNames.Sequence =>
            $"Number with “{step.Pattern}” as {Pos(step.Position)}, from {step.Start} step {step.Step}",
        OpNames.Case => $"Change case to {step.Mode}",
        OpNames.Extension =>
            string.Equals(step.Mode, "set", StringComparison.OrdinalIgnoreCase)
                ? $"Set the extension to “{step.Value}”"
                : $"Change the extension to {step.Mode}case",
        _ => $"(unknown op “{step.Op}”)",
    };

    private static string Pos(string? position) =>
        string.Equals(position, "suffix", StringComparison.OrdinalIgnoreCase) ? "suffix" : "prefix";

    public static RuleStep Create(string op) => op switch
    {
        OpNames.Replace => new RuleStep { Op = op, Find = "", ReplaceWith = "" },
        OpNames.Insert => new RuleStep { Op = op, Text = "", Position = "prefix" },
        OpNames.Remove => new RuleStep { Op = op, From = 0, Count = 1 },
        OpNames.Sequence => new RuleStep { Op = op, Pattern = "{n:000}_", Start = 1, Step = 1, Position = "prefix" },
        OpNames.Case => new RuleStep { Op = op, Mode = "lower" },
        OpNames.Extension => new RuleStep { Op = op, Mode = "lower", Value = "txt" },
        _ => new RuleStep { Op = op },
    };

    public static string Title(string op) => op switch
    {
        OpNames.Replace => "Find and replace",
        OpNames.Insert => "Insert text",
        OpNames.Remove => "Remove characters",
        OpNames.Sequence => "Numbering",
        OpNames.Case => "Letter case",
        OpNames.Extension => "Extension",
        _ => op,
    };

    public static string Hint(string op) => op switch
    {
        OpNames.Replace =>
            "Every occurrence is replaced. In regex mode the pattern is .NET regex and the "
            + "replacement may use $1, $2 ... to reference capture groups.",
        OpNames.Insert =>
            "“At position” counts from 0 and is clamped to the length of the target text.",
        OpNames.Remove =>
            "Both values are clamped: removing more characters than remain simply removes the rest.",
        OpNames.Sequence =>
            "The pattern may contain literal text plus one {n:000} token, where the zeros give the "
            + "padding width. The counter advances for every file in the list, including files that "
            + "end up skipped.",
        OpNames.Case =>
            "“Title” capitalises the first letter of every run of letters and lowercases the rest.",
        OpNames.Extension =>
            "This step always works on the extension, whatever the rule set applies to. A file "
            + "without an extension gains one when the mode is “set”.",
        _ => string.Empty,
    };
}

/// <summary>
/// The right-hand half of the rule pane: a form whose fields are rebuilt for whichever step is
/// selected. Every field writes straight through to the bound <see cref="RuleStep"/> and raises
/// <see cref="StepEdited"/>, which is what drives the live preview.
/// </summary>
internal sealed class StepEditorPanel : Panel
{
    private RuleStep? _step;

    public StepEditorPanel()
    {
        AutoScroll = true;
        Padding = new Padding(10, 8, 10, 8);
    }

    public event EventHandler? StepEdited;

    public void Bind(RuleStep? step)
    {
        _step = step;
        Rebuild();
    }

    private void Raise() => StepEdited?.Invoke(this, EventArgs.Empty);

    private void Rebuild()
    {
        SuspendLayout();
        foreach (Control existing in Controls)
        {
            existing.Dispose();
        }
        Controls.Clear();

        if (_step is null)
        {
            var empty = new Label
            {
                Text = "Select a step on the left to edit it,\nor add one with the “Add” button.",
                Dock = DockStyle.Top,
                AutoSize = true,
                ForeColor = SystemColors.GrayText,
            };
            Controls.Add(empty);
            ResumeLayout(true);
            return;
        }

        var op = (_step.Op ?? string.Empty).ToLowerInvariant();

        var grid = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 2,
        };
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 108));
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));

        switch (op)
        {
            case OpNames.Replace:
                AddRow(grid, "Find", TextBox(_step.Find, v => _step.Find = v));
                AddRow(grid, "Replace with", TextBox(_step.ReplaceWith, v => _step.ReplaceWith = v));
                AddRow(grid, string.Empty, CheckBox("Regular expression", _step.Regex, v => _step.Regex = v));
                AddRow(grid, string.Empty, CheckBox("Ignore case", _step.IgnoreCase, v => _step.IgnoreCase = v));
                break;

            case OpNames.Insert:
                AddRow(grid, "Text", TextBox(_step.Text, v => _step.Text = v));
                AddRow(grid, "Place", Choice(["prefix", "suffix", "index"], _step.Position ?? "prefix",
                    v => _step.Position = v));
                AddRow(grid, "At position", Number(_step.Index, v => _step.Index = v));
                break;

            case OpNames.Remove:
                AddRow(grid, "From position", Number(_step.From, v => _step.From = v));
                AddRow(grid, "How many", Number(_step.Count, v => _step.Count = v));
                break;

            case OpNames.Sequence:
                AddRow(grid, "Pattern", TextBox(_step.Pattern, v => _step.Pattern = v));
                AddRow(grid, "Place", Choice(["prefix", "suffix"], _step.Position ?? "prefix",
                    v => _step.Position = v));
                AddRow(grid, "Start at", Number(_step.Start, v => _step.Start = v));
                AddRow(grid, "Step by", Number(_step.Step, v => _step.Step = v));
                break;

            case OpNames.Case:
                AddRow(grid, "Mode", Choice(["upper", "lower", "title"], _step.Mode ?? "lower",
                    v => _step.Mode = v));
                break;

            case OpNames.Extension:
                AddRow(grid, "Mode", Choice(["lower", "upper", "set"], _step.Mode ?? "lower",
                    v => _step.Mode = v));
                AddRow(grid, "New extension", TextBox(_step.Value, v => _step.Value = v));
                break;
        }

        var hint = new Label
        {
            Text = RuleStepText.Hint(op),
            Dock = DockStyle.Top,
            AutoSize = true,
            MaximumSize = new Size(Math.Max(200, ClientSize.Width - 26), 0),
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(0, 10, 0, 0),
            Padding = new Padding(0, 10, 0, 0),
        };

        var header = new Label
        {
            Text = RuleStepText.Title(op),
            Dock = DockStyle.Top,
            AutoSize = true,
            Font = new Font(Font, FontStyle.Bold),
            Padding = new Padding(0, 0, 0, 6),
        };

        // Docked controls stack bottom-up in reverse order of adding.
        Controls.Add(hint);
        Controls.Add(grid);
        Controls.Add(header);
        ResumeLayout(true);
    }

    private static void AddRow(TableLayoutPanel grid, string label, Control control)
    {
        var row = grid.RowCount++;
        grid.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        grid.Controls.Add(new Label
        {
            Text = label,
            AutoSize = true,
            Anchor = AnchorStyles.Left,
            Margin = new Padding(0, 6, 6, 0),
        }, 0, row);
        control.Margin = new Padding(0, 3, 0, 3);
        grid.Controls.Add(control, 1, row);
    }

    private TextBox TextBox(string? value, Action<string> setter)
    {
        var box = new TextBox { Text = value ?? string.Empty, Dock = DockStyle.Fill };
        box.TextChanged += (_, _) =>
        {
            setter(box.Text);
            Raise();
        };
        return box;
    }

    private NumericUpDown Number(int value, Action<int> setter)
    {
        var spin = new NumericUpDown
        {
            Minimum = -1_000_000,
            Maximum = 1_000_000,
            Value = Math.Clamp(value, -1_000_000, 1_000_000),
            Width = 90,
            Anchor = AnchorStyles.Left,
        };
        spin.ValueChanged += (_, _) =>
        {
            setter((int)spin.Value);
            Raise();
        };
        return spin;
    }

    private CheckBox CheckBox(string text, bool value, Action<bool> setter)
    {
        var box = new CheckBox { Text = text, Checked = value, AutoSize = true, Anchor = AnchorStyles.Left };
        box.CheckedChanged += (_, _) =>
        {
            setter(box.Checked);
            Raise();
        };
        return box;
    }

    private ComboBox Choice(string[] items, string current, Action<string> setter)
    {
        var combo = new ComboBox
        {
            DropDownStyle = ComboBoxStyle.DropDownList,
            Width = 150,
            Anchor = AnchorStyles.Left,
        };
        combo.Items.AddRange(items);
        var index = Array.FindIndex(items, i => string.Equals(i, current, StringComparison.OrdinalIgnoreCase));
        combo.SelectedIndex = index >= 0 ? index : 0;
        combo.SelectedIndexChanged += (_, _) =>
        {
            setter((string)combo.SelectedItem!);
            Raise();
        };
        return combo;
    }
}

