using System.Text;
using System.Text.Json;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The single window: pick a folder on the left, stack up rule steps, watch the preview on the
/// right update as you type, then apply. Nothing is written to disk until "Apply rename" is
/// pressed, and every applied batch can be reversed afterwards.
/// </summary>
internal sealed class MainForm : Form
{
    private sealed record Choice(string Value, string Text)
    {
        public override string ToString() => Text;
    }

    private static readonly Color OkBack = Color.FromArgb(240, 249, 241);
    private static readonly Color UnchangedBack = Color.FromArgb(247, 247, 247);
    private static readonly Color CollisionBack = Color.FromArgb(255, 245, 219);
    private static readonly Color InvalidBack = Color.FromArgb(255, 234, 234);

    private readonly RuleSet _rules = new();
    private readonly RenameHistory _history = new();
    private readonly ToolTip _tips = new();

    private List<FileEntry> _files = [];
    private RenamePlan _plan = new();
    private string _directory = string.Empty;
    private bool _populating;
    private bool _ready;

    private readonly TextBox _folderBox = new();
    private readonly ListView _stepList = new();
    private readonly StepEditorPanel _editor = new();
    private readonly DataGridView _preview = new();
    private readonly ComboBox _applyToCombo = new();
    private readonly ComboBox _sortCombo = new();
    private readonly Label _summaryLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly ToolStripStatusLabel _status = new();

    public MainForm(string? initialDirectory)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(940, 560);
        Size = new Size(1180, 720);
        StartPosition = FormStartPosition.CenterScreen;
        AllowDrop = true;

        BuildLayout();
        WireEvents();

        _ready = true;
        RefreshStepList();
        UpdateUndoButton();

        var start = initialDirectory;
        if (string.IsNullOrWhiteSpace(start) || !Directory.Exists(start))
        {
            start = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
        }
        LoadFolder(start);
    }

    // ------------------------------------------------------------------ layout

    private void BuildLayout()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterDistance = 420,
            SplitterWidth = 6,
        };
        split.Panel1MinSize = 340;
        split.Panel2MinSize = 380;
        split.Panel1.Controls.Add(BuildRulePane());
        split.Panel2.Controls.Add(BuildPreviewPane());

        Controls.Add(split);
        Controls.Add(BuildActionBar());
        Controls.Add(BuildStatusBar());
        Controls.Add(BuildFolderBar());
        Controls.Add(BuildMenu());

        // The splitter distance only sticks once the container has its real width.
        Shown += (_, _) => split.SplitterDistance = Math.Min(430, Math.Max(340, ClientSize.Width / 3));
    }

    private MenuStrip BuildMenu()
    {
        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add(Menu("Open &folder…", Keys.Control | Keys.O, (_, _) => BrowseForFolder()));
        file.DropDownItems.Add(Menu("&Rescan folder", Keys.F5, (_, _) => Rescan()));
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(Menu("&Load rules…", Keys.Control | Keys.L, (_, _) => LoadRules()));
        file.DropDownItems.Add(Menu("&Save rules…", Keys.Control | Keys.S, (_, _) => SaveRules()));
        file.DropDownItems.Add(Menu("&Export plan.json…", Keys.Control | Keys.E, (_, _) => ExportPlan()));
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(Menu("E&xit", Keys.None, (_, _) => Close()));

        var rules = new ToolStripMenuItem("&Rules");
        var add = new ToolStripMenuItem("&Add step");
        foreach (var op in OpNames.All)
        {
            var captured = op;
            add.DropDownItems.Add(new ToolStripMenuItem(RuleStepText.Title(op), null,
                (_, _) => AddStep(captured)));
        }
        rules.DropDownItems.Add(add);
        rules.DropDownItems.Add(Menu("D&uplicate step", Keys.Control | Keys.D, (_, _) => DuplicateStep()));
        rules.DropDownItems.Add(Menu("&Remove step", Keys.None, (_, _) => RemoveStep()));
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add(Menu("Move &up", Keys.Control | Keys.Up, (_, _) => MoveStep(-1)));
        rules.DropDownItems.Add(Menu("Move &down", Keys.Control | Keys.Down, (_, _) => MoveStep(1)));
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add(Menu("&Clear all steps", Keys.None, (_, _) => ClearSteps()));

        var actions = new ToolStripMenuItem("&Actions");
        actions.DropDownItems.Add(Menu("&Apply rename", Keys.Control | Keys.Enter, (_, _) => ApplyRename()));
        actions.DropDownItems.Add(Menu("&Undo last rename", Keys.Control | Keys.Z, (_, _) => UndoLast()));

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add(Menu("&Command line and rule reference", Keys.F1, (_, _) => ShowReference()));
        help.DropDownItems.Add(Menu("&About", Keys.None, (_, _) => ShowAbout()));

        var menu = new MenuStrip();
        menu.Items.AddRange([file, rules, actions, help]);
        MainMenuStrip = menu;
        return menu;
    }

    private static ToolStripMenuItem Menu(string text, Keys shortcut, EventHandler handler)
    {
        var item = new ToolStripMenuItem(text, null, handler);
        if (shortcut != Keys.None)
        {
            item.ShortcutKeys = shortcut;
        }
        return item;
    }

    private Panel BuildFolderBar()
    {
        var browse = new Button { Text = "Browse…", Width = 90, Dock = DockStyle.Right };
        browse.Click += (_, _) => BrowseForFolder();
        var rescan = new Button { Text = "Rescan", Width = 80, Dock = DockStyle.Right };
        rescan.Click += (_, _) => Rescan();

        _folderBox.Dock = DockStyle.Fill;
        _folderBox.ReadOnly = true;
        _folderBox.BackColor = SystemColors.Window;

        var label = new Label { Text = "Folder", Dock = DockStyle.Left, Width = 52, TextAlign = ContentAlignment.MiddleLeft };

        var bar = new Panel { Dock = DockStyle.Top, Height = 36, Padding = new Padding(10, 6, 10, 4) };
        bar.Controls.Add(_folderBox);
        bar.Controls.Add(new Panel { Dock = DockStyle.Right, Width = 6 });
        bar.Controls.Add(rescan);
        bar.Controls.Add(new Panel { Dock = DockStyle.Right, Width = 6 });
        bar.Controls.Add(browse);
        bar.Controls.Add(label);
        return bar;
    }

    private Control BuildRulePane()
    {
        var layout = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(8, 6, 4, 6),
        };
        layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        layout.RowStyles.Add(new RowStyle(SizeType.Percent, 48F));
        layout.RowStyles.Add(new RowStyle(SizeType.Percent, 52F));

        layout.Controls.Add(BuildRuleOptions(), 0, 0);
        layout.Controls.Add(BuildStepList(), 0, 1);

        var editorBox = new GroupBox { Text = "Step settings", Dock = DockStyle.Fill };
        _editor.Dock = DockStyle.Fill;
        editorBox.Controls.Add(_editor);
        layout.Controls.Add(editorBox, 0, 2);

        return layout;
    }

    private Control BuildRuleOptions()
    {
        _applyToCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToCombo.Width = 170;
        _applyToCombo.Items.AddRange(
        [
            new Choice(ApplyToValues.Name, "File name only"),
            new Choice(ApplyToValues.NameAndExtension, "Name and extension"),
        ]);
        _applyToCombo.SelectedIndex = 0;

        _sortCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortCombo.Width = 170;
        _sortCombo.Items.AddRange(
        [
            new Choice(SortValues.Name, "Name (ordinal)"),
            new Choice(SortValues.Created, "Created date"),
            new Choice(SortValues.Modified, "Modified date"),
        ]);
        _sortCombo.SelectedIndex = 0;

        var grid = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            ColumnCount = 2,
            RowCount = 2,
        };
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 96));
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));
        grid.Controls.Add(new Label { Text = "Apply steps to", AutoSize = true, Anchor = AnchorStyles.Left }, 0, 0);
        grid.Controls.Add(_applyToCombo, 1, 0);
        grid.Controls.Add(new Label { Text = "Process order", AutoSize = true, Anchor = AnchorStyles.Left }, 0, 1);
        grid.Controls.Add(_sortCombo, 1, 1);

        var box = new GroupBox { Text = "Rule set", Dock = DockStyle.Fill, AutoSize = true, Padding = new Padding(8, 4, 8, 8) };
        box.Controls.Add(grid);
        return box;
    }

    private Control BuildStepList()
    {
        _stepList.View = View.Details;
        _stepList.CheckBoxes = true;
        _stepList.FullRowSelect = true;
        _stepList.MultiSelect = false;
        _stepList.HideSelection = false;
        _stepList.HeaderStyle = ColumnHeaderStyle.Nonclickable;
        _stepList.Dock = DockStyle.Fill;
        _stepList.Columns.Add("#", 40);
        _stepList.Columns.Add("Step", 320);

        var bar = new ToolStrip { Dock = DockStyle.Top, GripStyle = ToolStripGripStyle.Hidden };
        var add = new ToolStripDropDownButton("Add step")
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        };
        foreach (var op in OpNames.All)
        {
            var captured = op;
            add.DropDownItems.Add(new ToolStripMenuItem(RuleStepText.Title(op), null, (_, _) => AddStep(captured)));
        }
        bar.Items.Add(add);
        bar.Items.Add(Button("Duplicate", () => DuplicateStep()));
        bar.Items.Add(Button("Remove", () => RemoveStep()));
        bar.Items.Add(new ToolStripSeparator());
        bar.Items.Add(Button("Move up", () => MoveStep(-1)));
        bar.Items.Add(Button("Move down", () => MoveStep(1)));

        var box = new GroupBox { Text = "Steps (applied top to bottom)", Dock = DockStyle.Fill, Padding = new Padding(6, 4, 6, 6) };
        box.Controls.Add(_stepList);
        box.Controls.Add(bar);
        return box;
    }

    private static ToolStripButton Button(string text, Action action)
    {
        var button = new ToolStripButton(text) { DisplayStyle = ToolStripItemDisplayStyle.Text };
        button.Click += (_, _) => action();
        return button;
    }

    private Control BuildPreviewPane()
    {
        _preview.Dock = DockStyle.Fill;
        _preview.VirtualMode = true;
        _preview.ReadOnly = true;
        _preview.AllowUserToAddRows = false;
        _preview.AllowUserToDeleteRows = false;
        _preview.AllowUserToOrderColumns = false;
        _preview.AllowUserToResizeRows = false;
        _preview.RowHeadersVisible = false;
        _preview.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _preview.MultiSelect = false;
        _preview.BorderStyle = BorderStyle.None;
        _preview.BackgroundColor = SystemColors.Window;
        _preview.ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.DisableResizing;
        _preview.EnableHeadersVisualStyles = false;

        _preview.Columns.Add(Column("#", 46, DataGridViewAutoSizeColumnMode.None));
        _preview.Columns.Add(Column("Original name", 0, DataGridViewAutoSizeColumnMode.Fill, 34));
        _preview.Columns.Add(Column("Proposed name", 0, DataGridViewAutoSizeColumnMode.Fill, 34));
        _preview.Columns.Add(Column("Status", 92, DataGridViewAutoSizeColumnMode.None));
        _preview.Columns.Add(Column("Reason", 0, DataGridViewAutoSizeColumnMode.Fill, 32));

        var box = new GroupBox { Text = "Preview", Dock = DockStyle.Fill, Padding = new Padding(6, 4, 6, 6) };
        box.Controls.Add(_preview);
        return box;
    }

    private static DataGridViewTextBoxColumn Column(
        string header, int width, DataGridViewAutoSizeColumnMode mode, int fillWeight = 100)
    {
        var column = new DataGridViewTextBoxColumn
        {
            HeaderText = header,
            AutoSizeMode = mode,
            SortMode = DataGridViewColumnSortMode.NotSortable,
            FillWeight = fillWeight,
        };
        if (width > 0)
        {
            column.Width = width;
        }
        return column;
    }

    private Control BuildActionBar()
    {
        _summaryLabel.Dock = DockStyle.Fill;
        _summaryLabel.TextAlign = ContentAlignment.MiddleLeft;
        _summaryLabel.Text = "No folder loaded.";

        _applyButton.Text = "Apply rename";
        _applyButton.Width = 130;
        _applyButton.Height = 30;
        _applyButton.Enabled = false;
        _applyButton.Click += (_, _) => ApplyRename();

        _undoButton.Text = "Undo last rename";
        _undoButton.Width = 140;
        _undoButton.Height = 30;
        _undoButton.Enabled = false;
        _undoButton.Click += (_, _) => UndoLast();

        var layout = new TableLayoutPanel
        {
            Dock = DockStyle.Bottom,
            Height = 46,
            ColumnCount = 3,
            RowCount = 1,
            Padding = new Padding(10, 6, 10, 6),
        };
        layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));
        layout.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        layout.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        layout.Controls.Add(_summaryLabel, 0, 0);
        layout.Controls.Add(_undoButton, 1, 0);
        layout.Controls.Add(_applyButton, 2, 0);
        return layout;
    }

    private StatusStrip BuildStatusBar()
    {
        _status.Spring = true;
        _status.TextAlign = ContentAlignment.MiddleLeft;
        var strip = new StatusStrip();
        strip.Items.Add(_status);
        return strip;
    }

    // ------------------------------------------------------------------ events

    private void WireEvents()
    {
        _applyToCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = ((Choice)_applyToCombo.SelectedItem!).Value;
            RefreshPreview();
        };
        _sortCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = ((Choice)_sortCombo.SelectedItem!).Value;
            RefreshPreview();
        };

        _stepList.SelectedIndexChanged += (_, _) =>
        {
            var index = SelectedStepIndex;
            _editor.Bind(index >= 0 ? _rules.Steps[index] : null);
        };
        _stepList.ItemChecked += (_, e) =>
        {
            if (_populating)
            {
                return;
            }
            var index = e.Item.Index;
            if (index >= 0 && index < _rules.Steps.Count)
            {
                _rules.Steps[index].Enabled = e.Item.Checked;
                RefreshPreview();
            }
        };
        _stepList.KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.Delete)
            {
                RemoveStep();
                e.Handled = true;
            }
        };

        _editor.StepEdited += (_, _) =>
        {
            var index = SelectedStepIndex;
            if (index >= 0 && index < _stepList.Items.Count)
            {
                _stepList.Items[index].SubItems[1].Text = RuleStepText.Describe(_rules.Steps[index]);
            }
            RefreshPreview();
        };

        _preview.CellValueNeeded += (_, e) =>
        {
            if (e.RowIndex < 0 || e.RowIndex >= _plan.Items.Count)
            {
                return;
            }
            var item = _plan.Items[e.RowIndex];
            e.Value = e.ColumnIndex switch
            {
                0 => (e.RowIndex + 1).ToString(),
                1 => item.Original,
                2 => item.Proposed,
                3 => item.Status,
                _ => item.Reason,
            };
        };
        _preview.CellFormatting += (_, e) =>
        {
            if (e.RowIndex < 0 || e.RowIndex >= _plan.Items.Count)
            {
                return;
            }
            var status = _plan.Items[e.RowIndex].Status;
            e.CellStyle.BackColor = status switch
            {
                PlanStatus.Ok => OkBack,
                PlanStatus.Unchanged => UnchangedBack,
                PlanStatus.Collision => CollisionBack,
                _ => InvalidBack,
            };
            e.CellStyle.ForeColor = status switch
            {
                PlanStatus.Unchanged => SystemColors.GrayText,
                PlanStatus.Invalid => Color.FromArgb(150, 20, 20),
                _ => SystemColors.ControlText,
            };
        };

        DragEnter += (_, e) =>
        {
            if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
            {
                e.Effect = DragDropEffects.Copy;
            }
        };
        DragDrop += (_, e) =>
        {
            if (e.Data?.GetData(DataFormats.FileDrop) is string[] { Length: > 0 } paths)
            {
                var path = Directory.Exists(paths[0]) ? paths[0] : Path.GetDirectoryName(paths[0]);
                if (!string.IsNullOrEmpty(path))
                {
                    LoadFolder(path);
                }
            }
        };
    }

    private int SelectedStepIndex =>
        _stepList.SelectedIndices.Count > 0 ? _stepList.SelectedIndices[0] : -1;

    // ------------------------------------------------------------------ folder

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog
        {
            Description = "Choose the folder whose files should be renamed",
            UseDescriptionForTitle = true,
            ShowNewFolderButton = false,
        };
        if (Directory.Exists(_directory))
        {
            dialog.SelectedPath = _directory;
        }
        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            LoadFolder(dialog.SelectedPath);
        }
    }

    private void LoadFolder(string path)
    {
        _directory = path;
        _folderBox.Text = path;
        Rescan();
    }

    private void Rescan()
    {
        if (string.IsNullOrEmpty(_directory) || !Directory.Exists(_directory))
        {
            _files = [];
            RefreshPreview();
            return;
        }
        try
        {
            _files = FileScanner.Scan(_directory);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            _files = [];
            MessageBox.Show(this, $"The folder could not be read.\n\n{ex.Message}",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        RefreshPreview();
    }

    // ------------------------------------------------------------------ steps

    private void AddStep(string op)
    {
        _rules.Steps.Add(RuleStepText.Create(op));
        RefreshStepList(_rules.Steps.Count - 1);
        RefreshPreview();
    }

    private void DuplicateStep()
    {
        var index = SelectedStepIndex;
        if (index < 0)
        {
            return;
        }
        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        RefreshStepList(index + 1);
        RefreshPreview();
    }

    private void RemoveStep()
    {
        var index = SelectedStepIndex;
        if (index < 0)
        {
            return;
        }
        _rules.Steps.RemoveAt(index);
        RefreshStepList(Math.Min(index, _rules.Steps.Count - 1));
        RefreshPreview();
    }

    private void MoveStep(int delta)
    {
        var index = SelectedStepIndex;
        var target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }
        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RefreshStepList(target);
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0)
        {
            return;
        }
        if (MessageBox.Show(this, "Remove every step from the rule set?", "Batch Rename Studio",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }
        _rules.Steps.Clear();
        RefreshStepList();
        RefreshPreview();
    }

    private void RefreshStepList(int selectIndex = -1)
    {
        _populating = true;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            var step = _rules.Steps[i];
            var item = new ListViewItem((i + 1).ToString()) { Checked = step.Enabled };
            item.SubItems.Add(RuleStepText.Describe(step));
            _stepList.Items.Add(item);
        }
        _stepList.EndUpdate();
        _populating = false;

        if (selectIndex >= 0 && selectIndex < _stepList.Items.Count)
        {
            _stepList.Items[selectIndex].Selected = true;
            _stepList.Items[selectIndex].Focused = true;
        }
        else
        {
            _editor.Bind(null);
        }
    }

    // ------------------------------------------------------------------ preview

    private void RefreshPreview()
    {
        if (!_ready)
        {
            return;
        }

        _plan = RenameEngine.BuildPlan(_files, _rules.WithEnabledStepsOnly());

        _preview.RowCount = _plan.Items.Count;
        _preview.Invalidate();

        var s = _plan.Summary;
        _summaryLabel.Text = _files.Count == 0
            ? "No files in this folder."
            : $"{s.Total} file(s)   ·   {s.Ok} to rename   ·   {s.Unchanged} unchanged   ·   " +
              $"{s.Collision} collision   ·   {s.Invalid} invalid";
        _applyButton.Enabled = s.Ok > 0;

        _status.Text = _plan.Warnings.Count > 0
            ? "⚠ " + string.Join("   ·   ", _plan.Warnings)
            : _directory.Length > 0 ? _directory : "No folder selected.";
    }

    // ------------------------------------------------------------------ rules I/O

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load a rule set",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            var loaded = RuleSet.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            SelectChoice(_applyToCombo, _rules.ApplyTo);
            SelectChoice(_sortCombo, _rules.Sort);
            RefreshStepList(_rules.Steps.Count > 0 ? 0 : -1);
            RefreshPreview();
            _status.Text = $"Loaded {Path.GetFileName(dialog.FileName)}";
        }
        catch (Exception ex) when (ex is IOException or JsonException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, $"That rule set could not be loaded.\n\n{ex.Message}",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save the rule set",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            File.WriteAllText(dialog.FileName, _rules.ToJson(), new UTF8Encoding(false));
            _status.Text = $"Saved {Path.GetFileName(dialog.FileName)} (disabled steps are not written)";
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, $"The rule set could not be saved.\n\n{ex.Message}",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Export the current preview as plan.json",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            _plan.WriteTo(dialog.FileName);
            _status.Text = $"Exported {Path.GetFileName(dialog.FileName)}";
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, $"The plan could not be exported.\n\n{ex.Message}",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private static void SelectChoice(ComboBox combo, string value)
    {
        for (var i = 0; i < combo.Items.Count; i++)
        {
            if (combo.Items[i] is Choice choice
                && string.Equals(choice.Value, value, StringComparison.OrdinalIgnoreCase))
            {
                combo.SelectedIndex = i;
                return;
            }
        }
        combo.SelectedIndex = 0;
    }

    // ------------------------------------------------------------------ apply / undo

    private void ApplyRename()
    {
        if (_plan.Summary.Ok == 0)
        {
            MessageBox.Show(this, "There is nothing to rename with the current rules.",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var skipped = _plan.Summary.Total - _plan.Summary.Ok;
        var message = $"Rename {_plan.Summary.Ok} file(s) in\n{_directory}\n\n"
                      + (skipped > 0 ? $"{skipped} file(s) will be left alone.\n\n" : string.Empty)
                      + "This can be reversed with “Undo last rename”.";
        if (MessageBox.Show(this, message, "Apply rename", MessageBoxButtons.OKCancel,
                MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var outcome = RenameApplier.Apply(_directory, _plan);
        if (outcome.Batch is not null)
        {
            _history.Add(outcome.Batch);
        }
        Rescan();
        UpdateUndoButton();

        if (outcome.Failures.Count > 0)
        {
            MessageBox.Show(this,
                $"Renamed {outcome.Renamed} file(s); {outcome.Failures.Count} could not be renamed:\n\n"
                + string.Join("\n", outcome.Failures.Take(15)),
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        else
        {
            _status.Text = $"Renamed {outcome.Renamed} file(s).";
        }
    }

    private void UndoLast()
    {
        var batch = _history.Newest;
        if (batch is null)
        {
            return;
        }

        var message = $"Put {batch.Records.Count} file name(s) back as they were?\n\n{batch.Label}";
        if (MessageBox.Show(this, message, "Undo last rename", MessageBoxButtons.OKCancel,
                MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var failures = RenameApplier.Undo(batch);
        _history.Remove(batch);
        Rescan();
        UpdateUndoButton();

        if (failures.Count > 0)
        {
            MessageBox.Show(this,
                $"{failures.Count} file(s) could not be restored:\n\n" + string.Join("\n", failures.Take(15)),
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        else
        {
            _status.Text = $"Restored {batch.Records.Count} file name(s).";
        }
    }

    private void UpdateUndoButton()
    {
        var batch = _history.Newest;
        _undoButton.Enabled = batch is not null;
        _tips.SetToolTip(_undoButton, batch is null
            ? "Nothing has been renamed yet."
            : $"Undo: {batch.Label}");
    }

    // ------------------------------------------------------------------ help

    private void ShowReference()
    {
        using var dialog = new Form
        {
            Text = "Command line and rule reference",
            Size = new Size(760, 620),
            StartPosition = FormStartPosition.CenterParent,
            MinimizeBox = false,
            MaximizeBox = false,
        };
        var text = new TextBox
        {
            Multiline = true,
            ReadOnly = true,
            ScrollBars = ScrollBars.Vertical,
            Dock = DockStyle.Fill,
            Font = new Font(FontFamily.GenericMonospace, 9F),
            WordWrap = false,
            Text = CommandLine.HelpText.ReplaceLineEndings() + Environment.NewLine
                   + Environment.NewLine + ReferenceText.ReplaceLineEndings(),
        };
        dialog.Controls.Add(text);
        dialog.ShowDialog(this);
    }

    private void ShowAbout() =>
        MessageBox.Show(this,
            "Batch Rename Studio 1.0\n\n"
            + "Preview-first batch renaming for Windows.\n"
            + "Nothing is written to disk until you press “Apply rename”, and every applied batch "
            + "can be undone — even after restarting the program.",
            "About Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Information);

    private const string ReferenceText = """
        Rule set file (rules.json)
        --------------------------
        {
          "applyTo": "name" | "nameAndExtension",
          "sort":    "name" | "created" | "modified",
          "steps": [
            {"op":"replace",   "find":"...", "replaceWith":"...", "regex":false, "ignoreCase":false},
            {"op":"insert",    "text":"...", "position":"prefix"|"suffix"|"index", "index":0},
            {"op":"remove",    "from":0, "count":3},
            {"op":"sequence",  "pattern":"{n:000}_", "start":1, "step":1, "position":"prefix"|"suffix"},
            {"op":"case",      "mode":"upper"|"lower"|"title"},
            {"op":"extension", "mode":"lower"|"upper"|"set", "value":"txt"}
          ]
        }

        How a name is taken apart
        -------------------------
        The extension starts after the LAST dot, and only when that dot is not the first
        character. So "archive.tar.gz" has the base "archive.tar" and the extension "gz",
        while ".gitignore" is all base and has no extension.

        Statuses in the preview
        -----------------------
        invalid    the proposed name is empty, longer than 255 characters, contains one of
                   < > : " / \ | ? * or a control character, or its base is a reserved
                   Windows device name (CON, PRN, AUX, NUL, COM1-9, LPT1-9).
        collision  another file in the folder already has that name, or another row in the
                   preview wants the same name. Compared without regard to letter case.
        unchanged  the rules produced exactly the original name.
        ok         the file will be renamed.

        Only "ok" rows are renamed when you press Apply.
        """;
}

