using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Core;

/// <summary>
/// The four statuses defined by the contract, in the order they are evaluated.
/// </summary>
public static class PlanStatus
{
    public const string Invalid = "invalid";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Ok = "ok";
}

/// <summary>One planned rename. Property order here is the property order in plan.json.</summary>
public sealed class PlanItem
{
    [JsonPropertyName("original")]
    public string Original { get; set; } = string.Empty;

    [JsonPropertyName("proposed")]
    public string Proposed { get; set; } = string.Empty;

    [JsonPropertyName("status")]
    public string Status { get; set; } = PlanStatus.Ok;

    [JsonPropertyName("reason")]
    public string Reason { get; set; } = string.Empty;
}

public sealed class PlanSummary
{
    [JsonPropertyName("total")]
    public int Total { get; set; }

    [JsonPropertyName("ok")]
    public int Ok { get; set; }

    [JsonPropertyName("collision")]
    public int Collision { get; set; }

    [JsonPropertyName("unchanged")]
    public int Unchanged { get; set; }

    [JsonPropertyName("invalid")]
    public int Invalid { get; set; }
}

public sealed class RenamePlan
{
    [JsonPropertyName("schemaVersion")]
    public int SchemaVersion { get; set; } = 1;

    [JsonPropertyName("items")]
    public List<PlanItem> Items { get; set; } = [];

    [JsonPropertyName("summary")]
    public PlanSummary Summary { get; set; } = new();

    /// <summary>
    /// Non-fatal notes produced while compiling the rule set (unknown op, bad regex, ...).
    /// Never part of plan.json; surfaced on stderr / in the GUI status bar.
    /// </summary>
    [JsonIgnore]
    public List<string> Warnings { get; } = [];

    private static readonly JsonSerializerOptions WriteOptions = new()
    {
        WriteIndented = true,
        // Relaxed escaping keeps non-ASCII file names readable in the output document; the result
        // is still strictly valid JSON, and the writer is deterministic either way.
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public string ToJson() => JsonSerializer.Serialize(this, WriteOptions);

    /// <summary>Writes plan.json as UTF-8 without a byte-order mark.</summary>
    public void WriteTo(string path)
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        // File.WriteAllText with UTF8Encoding(false) emits no BOM and performs no newline
        // translation, so the bytes are exactly the serializer's output.
        File.WriteAllText(path, ToJson(), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
    }

    public string SummaryLine(string outputPath) =>
        $"plan: total={Summary.Total} ok={Summary.Ok} collision={Summary.Collision} " +
        $"unchanged={Summary.Unchanged} invalid={Summary.Invalid} -> {outputPath}";
}

