/// <summary>
/// The only case that touches a real disk: apply a plan in a scratch folder, confirm the files
/// moved, then undo and confirm every original name came back. This is what backs the promise
/// that a rename can always be reversed.
/// </summary>
private static void ApplyAndUndoRoundTrip()
{
    var root = Path.Combine(Path.GetTempPath(), "brs-selftest-" + Guid.NewGuid().ToString("N"));
    try
    {
        var work = Path.Combine(root, "files");
        Directory.CreateDirectory(work);
        var originals = new[] { "a.txt", "b.txt", "keep.md", "case.txt" };
        foreach (var name in originals)
        {
            File.WriteAllText(Path.Combine(work, name), name);
        }

        var rules = RuleSet.Parse(Rules("name", "name",
            """{"op":"sequence","pattern":"{n:00}_","start":1,"step":1,"position":"prefix"}"""));
        var plan = RenameEngine.BuildPlan(work, rules);

        var history = new RenameHistory(Path.Combine(root, "history"));
        var outcome = RenameApplier.Apply(work, plan);
        if (outcome.Batch is not null)
        {
            history.Add(outcome.Batch);
        }

        var afterApply = Snapshot(work);
        var expected = string.Join("|", plan.Items
            .Where(i => i.Status == PlanStatus.Ok)
            .Select(i => i.Proposed)
            .OrderBy(n => n, StringComparer.Ordinal));
        Assert("apply / the ok rows are the names on disk", afterApply == expected,
            $"expected {expected} but found {afterApply}");
        Assert("apply / nothing failed", outcome.Failures.Count == 0,
            string.Join("; ", outcome.Failures));

        // The history must survive a fresh read of the same folder, which is what makes undo
        // work after a restart.
        var reloaded = new RenameHistory(Path.Combine(root, "history"));
        Assert("history / the batch is persisted", reloaded.Newest is not null, "no batch found");

        var failures = RenameApplier.Undo(reloaded.Newest!);
        Assert("undo / nothing failed", failures.Count == 0, string.Join("; ", failures));
        Assert("undo / every original name is back",
            Snapshot(work) == string.Join("|", originals.OrderBy(n => n, StringComparer.Ordinal)),
            Snapshot(work));

        // A rename that only changes letter case has to survive the same round trip.
        var caseRules = RuleSet.Parse(Rules("name", "name", """{"op":"case","mode":"upper"}"""));
        var casePlan = RenameEngine.BuildPlan(work, caseRules);
        var caseOutcome = RenameApplier.Apply(work, casePlan);
        Assert("apply / case-only renames succeed",
            caseOutcome.Failures.Count == 0 && Snapshot(work).Contains("A.txt", StringComparison.Ordinal),
            Snapshot(work));
        if (caseOutcome.Batch is not null)
        {
            RenameApplier.Undo(caseOutcome.Batch);
        }
        Assert("undo / case-only renames are reversed",
            Snapshot(work) == string.Join("|", originals.OrderBy(n => n, StringComparer.Ordinal)),
            Snapshot(work));
    }
    catch (Exception ex)
    {
        Failures.Add($"apply/undo round trip: threw {ex.GetType().Name}: {ex.Message}");
    }
    finally
    {
        try
        {
            if (Directory.Exists(root))
            {
                Directory.Delete(root, recursive: true);
            }
        }
        catch (IOException)
        {
        }
    }
}

private static string Snapshot(string directory) =>
    string.Join("|", new DirectoryInfo(directory).EnumerateFiles()
        .Select(f => f.Name)
        .OrderBy(n => n, StringComparer.Ordinal));

private static void Assert(string name, bool condition, string detail)
{
    if (condition)
    {
        _passed++;
    }
    else
    {
        Failures.Add($"{name}: {detail}");
    }
}

// ------------------------------------------------------------------ helpers

