        Assert("undo / nothing failed", failures.Count == 0, string.Join("; ", failures));
        Assert("undo / every original name is back",
            Snapshot(work) == string.Join("|", originals.OrderBy(n => n, StringComparer.Ordinal)),
            Snapshot(work));

        // A rename that only changes letter case has to survive the same round trip.
        var caseRules = RuleSet.Parse(Rules("name", "name", """{"op":"case","mode":"upper"}"""));
        var casePlan = RenameEngine.BuildPlan(work, caseRules);
        var caseOutcome = RenameApplier.Apply(work, casePlan);
        Assert("apply / case-only renames succeed",
            caseOutcome.Failures.Count == 0 && Snapshot(work).Contains("A.txt", StringComparison.Ordinal),
            Snapshot(work));
        if (caseOutcome.Batch is not null)
        {
            RenameApplier.Undo(caseOutcome.Batch);
        }
        Assert("undo / case-only renames are reversed",
            Snapshot(work) == string.Join("|", originals.OrderBy(n => n, StringComparer.Ordinal)),
            Snapshot(work));
    }
    catch (Exception ex)
    {
        Failures.Add($"apply/undo round trip: threw {ex.GetType().Name}: {ex.Message}");
    }
    finally
    {
        try
        {
            if (Directory.Exists(root))
            {
                Directory.Delete(root, recursive: true);
            }
        }
        catch (IOException)
        {
        }
    }
}

private static string Snapshot(string directory) =>
    string.Join("|", new DirectoryInfo(directory).EnumerateFiles()
        .Select(f => f.Name)
        .OrderBy(n => n, StringComparer.Ordinal));

private static void Assert(string name, bool condition, string detail)
{
    if (condition)
    {
        _passed++;
    }
    else
    {
        Failures.Add($"{name}: {detail}");
    }
}

